"""Current-review narrative and provenance; the original rubric remains in analyze.py."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
OWNED = ['folio', 'atelier', 'nocturne', 'tufte', 'zephyr-reading', 'simplex-reading', 'pulse-reading', 'litera-reading', 'darkly-reading']
BASELINES = dict(folio='folio-original', atelier='atelier-original', nocturne='nocturne-original', **{n: n.removesuffix('-reading') for n in OWNED if n.endswith('-reading')})
E = html.escape


def history_table(data):
    before = {t['id']: t for t in json.loads((ROOT / 'previous-scores.json').read_text())}
    current = {t['id']: t for t in data}
    rows = []
    for name in OWNED:
        a, b = before[name], current[name]
        original = current.get(BASELINES.get(name))
        baseline = f'{original["typography"]} / {original["design"]["total"]}' if original else 'October baseline'
        rows.append(f'<tr><th scope="row"><a href="#theme-{name}">{E(b["name"])}</a></th><td>{baseline}</td><td>{a["typography"]} / {a["design"]["total"]}</td><td><strong>{b["typography"]} / {b["design"]["total"]}</strong></td><td>{b["typography"]-a["typography"]:+d} / {b["design"]["total"]-a["design"]["total"]:+d}</td></tr>')
    return '<div class="table-wrap"><table class="rubric"><caption>Typography / design, each out of 100. October → November uses the same rubric.</caption><thead><tr><th>Owned theme</th><th>Original custom / stock</th><th>16 October</th><th>10 November</th><th>Change since October</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div><p class="caption">The original custom snapshots and stock themes are unchanged. Current owned themes use the lower of both mode scores; the October Reading themes had only their native mode. Expand a theme to see each current mode. Tufte had no separate original snapshot; its October result is preserved in the archive.</p>'


def current_intro(data):
    return '''<section id="changes"><h2>Nine updated themes, the same scorecard</h2><p>The 10 November review imports the exact nine merged foundation revisions verified upstream on 9 November. All nine now have explicit light/dark palettes, semantic roles, reading and presentation profiles, spacing, shape, and state pairs. The gallery exercises their reading profiles. The 25 stock Bootswatches, native Bootstrap, and three original custom snapshots remain unchanged.</p>'''+history_table(data)+'''<div class="callout"><p><strong>A lower typography score is a real rubric tradeoff.</strong> The new themes deliberately use 1.60 leading. The unchanged Butterick bands award that 12/20, compared with 20/20 at 1.20–1.45. Larger 18–20px prose, 16px code, and explicit controls can improve practical use while aligning less closely with this prescriptive scorecard. The score measures fit to the rubric; it is not a reader study.</p></div><p>Folio now uses Source Serif 4 for ordinary headings; Caslon is an optional display role. Atelier uses 18px DM Sans. Folio, Nocturne, Tufte, and Litera Reading use 20px serif prose. The other Reading themes use 18px prose. All nine use 16px code, 16px interface text, 14px metadata roles, 36px titles, and a separate optional 48px display role. Presentation sizes are published for downstream consumers and do not enlarge the document interface.</p><p><a href="history/2026-10-16/typography-report.html">Read the unchanged October typography report</a> · <a href="history/2026-10-16/visual-design-report.html">October design report</a> · <a href="theme-guide.html">Current theme handbook</a> · <a href="./?group=comparisons">Compare the actual pages</a></p></section>'''


def foundations_section():
    checks = json.loads((ROOT / 'foundations-checks.json').read_text())
    total = sum(len(r['sourceChecks']) for r in checks)
    failures = [(r, b, c) for r in checks for b in r['browser'] if b['viewport'] == 'desktop' for c in b['renderedText'] if not c['passes']]
    rows = ''.join(f'<tr><th>{E(r["id"])} / {r["mode"]}</th><td>{E(c["label"].removeprefix("foundation-"))}</td><td>{c["ratio"]:.2f}:1</td><td><a href="previews/{r["id"]}/foundations.html?mode={r["mode"]}">Actual specimen</a></td></tr>' for r, b, c in failures)
    profiles = [(r['id'], r['mode'], b['viewport'], b['profileErrors']) for r in checks for b in r['browser'] if b['profileErrors']]
    profile_note = 'The sampled body, interface, code, and caption roles match their declared sizes at both widths; no page overflow was measured.' if not profiles else f'{len(profiles)} profile contexts need inspection; see the raw foundation checks.'
    return f'''<section id="foundations"><h2>Beyond the score: foundations and remaining repairs</h2><p>The new supplementary specimen exercises semantic success/warning/danger/info actions, disabled buttons, associated error feedback, a selected navigation pill, captions, and form controls. It adds 36 browser observations, nine themes × two modes × two widths. These checks supplement the two fixed rubrics; they do not add points.</p><p><strong>{total} intended source color pairs clear their stated thresholds:</strong> 5:1 ordinary roles on paper/panel/code and state text on state fills, 4.5:1 primary/hover/selected action ink, and 3:1 meaningful edges. This checks opaque sRGB pairs from the committed manifests. It does not prove that every Bootstrap selector maps to those roles. {profile_note}</p><div class="table-wrap"><table class="rubric"><caption>Rendered component flags, observed at both 1280px and 390px</caption><thead><tr><th>Context</th><th>Component</th><th>Contrast</th><th>Evidence</th></tr></thead><tbody>{rows}</tbody></table></div><p><strong>Pulse Reading dark:</strong> the normal secondary button retains a white fill beneath pale text, giving 1.18:1. Its semantic role pair is sound, but this rendered component does not use the intended panel fill. <strong>Litera Reading, both modes:</strong> an active Bootstrap navigation pill retains a blue/white pair at 3.71:1. Explicit current-page semantics do not fix its color mapping.</p><p><strong>Darkly Reading light:</strong> the original code specimen has a sampled syntax minimum of 4.34:1. Base code ink clears the foundation check; at least one highlight color does not. This flag contributes to its typography deduction. These three findings need source fixes if the affected components or mode are used; the analysis does not silently alter the upstream themes.</p><div class="grid"><figure class="evidence"><img src="typography-audit/assets/pulse-reading-dark-desktop-components.jpg" alt="Pulse Reading dark with a pale secondary label on a white button" loading="lazy"><figcaption>Pulse Reading dark. Compare the secondary action with the primary and outline actions.</figcaption></figure><figure class="evidence"><img src="typography-audit/assets/darkly-reading-light-desktop-code.jpg" alt="Darkly Reading light code specimen with a below-threshold sampled syntax color" loading="lazy"><figcaption>Darkly Reading light. A readable base color does not guarantee readable highlighting.</figcaption></figure></div><p><a href="typography-audit/foundations-checks.json">All source and rendered foundation checks</a> · <a href="typography-audit/foundations-measurements.json">Raw foundation measurements</a> · <a href="typography-audit/current-screenshots.json">Current screenshot inventory</a></p><p class="caption">This is a controlled browser review, not whole-page accessibility certification. Disabled text is inspected as a usability choice, not treated as a normative contrast requirement. Assistive technology, every interactive state, zoom, physical devices, and room projection are not certified. Quarto consumer validation is recorded upstream; these fresh scores use SmallDocs only.</p></section>'''


def source_table():
    pins = json.loads((ROOT.parents[1] / 'theme-sources.json').read_text())
    rows = ''.join(f'<tr><th>{E(p["name"])}</th><td><a href="{p["repository"]}/commit/{p["commit"]}"><code>{p["commit"][:12]}</code></a></td><td><code>{p["foundations_sha256"]}</code></td></tr>' for p in pins if p['name'] in OWNED)
    return '<h3>Exact current source identities</h3><div class="table-wrap"><table class="rubric"><thead><tr><th>Theme</th><th>Commit</th><th>Foundation SHA-256</th></tr></thead><tbody>'+rows+'</tbody></table></div>'


METHOD = '''<section id="method"><h2>What was evaluated</h2><p>The comparison still contains 38 designs. Thirteen have paired light/dark styles: nine current owned themes, three original custom snapshots, and the native Bootstrap baseline. The other 25 are unchanged stock Bootswatches. This gives 51 theme/mode combinations. Companion modes belong to the owned Reading adaptations; they are not presented as upstream Bootswatch releases.</p><p>All 18 owned theme/mode combinations were freshly captured at 1280 × 844 and 390 × 844 CSS pixels on the identical Typography and Code specimens, plus desktop Controls: 72 prose/code and 18 control observations. Unchanged stock, Bootstrap, and original custom observations are carried forward from October after verifying their assets. The combined score dataset has 204 prose/code and 51 desktop control observations. The separate Foundations specimen adds 36 observations.</p><p>Captures use actual fixed-width iframes in the same browser. This tests CSS reflow, not physical-device behavior. Each capture awaits font loading and the declared CSS color-transition duration before sampling. Saved current images show the first 650px of each frame; full pages remain in the gallery. The committed browser harness, raw observations, screenshot inventory, source revisions, and SHA-256 manifest hashes accompany this report.</p><h3>Measurement and judgment</h3><ul><li>The two short prose paragraphs are unchanged. Character counts use rendered character-range geometry and exclude the final line of each paragraph. Roughly 490 characters estimate line capacity; a long chapter may move a borderline result.</li><li>Each mode is scored independently. The lower light/dark total becomes the theme score. The new Reading companions therefore expand the tested scope compared with October's native-only Reading modes.</li><li>All typography weights and deduction bands are unchanged. The design rubric and editorial judgment anchors are unchanged. Existing hierarchy, grouping, layout, surface, and personality awards are retained where the new specimens show no material reason to change them; measured color points are recalculated.</li><li>Contrast composites ancestor colors in sRGB. Quartz's horizontal gradient is sampled across the reading column; component gradients and Vapor's vertical gradient use conservative stop ranges. These old gradient estimates still need pixel-location verification for sign-off.</li><li>The fixed scores cover sampled normal-state text. The separate foundation checks cover intended source pairs and selected rendered roles; they do not certify every interaction state, icon, syntax class, device, or accessibility criterion.</li><li>The shared specimen does not exercise sidebars, contents panels, marginal notes, or complex Tufte columns. The pinned upstream repositories include separate SmallDocs and Quarto consumers and browser helpers; their evidence is supplementary, not a fresh Quarto score here.</li><li>This is a self-review using explicit measurements and editorial awards, not an independent reader study or endorsement. A high score means close alignment with this short rubric. Treat small differences as ties and inspect flagged components before adopting a theme.</li></ul><p class="caption">Reviewed 10 November 2026. The October reports, measurements, scores, and screenshots are preserved in <a href="history/2026-10-16/">the review archive</a>. The earlier source snapshot is <code>69c7339</code>; the original custom designs remain at tag <code>before-reading-redesign-2026-10-16</code>. No proprietary PDF or extracts are distributed.</p>'''+source_table()+'</section>'
